-- будує джерела (деталі) і Union-и нових шматків руди / злитків
local NAMES={coal="ChunkCoal",copper="ChunkCopper",iron="ChunkIron",barCu="BarCopper",barFe="BarIron"}
local O=CFrame.new(0,800,0)
local src=game.ServerStorage:FindFirstChild("ForgeChunkSources") or Instance.new("Folder",game.ServerStorage); src.Name="ForgeChunkSources"
local props=game.ReplicatedStorage.Prefabs.ForgeProps
local out={}
for key,rows in pairs(D) do
  local old=src:FindFirstChild(NAMES[key]); if old then old:Destroy() end
  local m=Instance.new("Model"); m.Name=NAMES[key]
  local parts={}
  for i,r in ipairs(rows) do
    local p
    if r[1]=='a' then
      p=Instance.new("Part"); p.Size=Vector3.new(r[2],r[3],r[4]); p.CFrame=O*CFrame.new(r[5],r[6],r[7]); p.Color=Color3.new(0,0,0); p.Name="Anchor"
    else
      p=Instance.new(r[1]=='b' and "Part" or r[1]=='w' and "WedgePart" or "CornerWedgePart")
      p.Size=Vector3.new(r[2],r[3],r[4])
      p.CFrame=O*CFrame.new(r[5],r[6],r[7],r[8],r[9],r[10],r[11],r[12],r[13],r[14],r[15],r[16])
      p.Color=Color3.fromHex(r[17]); p.Name="P"..i
    end
    p.Anchored=true; p.CanCollide=false; p.Material=Enum.Material.Plastic; p.MaterialVariant="StudsSmall"
    p.TopSurface=Enum.SurfaceType.Smooth; p.BottomSurface=Enum.SurfaceType.Smooth
    p.Parent=m; table.insert(parts,p)
  end
  m.WorldPivot=O
  m.Parent=src
  -- union (перша деталь — маленький «якір» по осях усередині тіла, щоб Union був вирівняний по осях)
  local work={} for _,p in ipairs(parts) do local c=p:Clone(); c.Parent=workspace; table.insert(work,c) end
  local base=table.remove(work,1)
  local ok,u=pcall(function() return base:UnionAsync(work, Enum.CollisionFidelity.Box, Enum.RenderFidelity.Precise) end)
  for _,c in ipairs(work) do c:Destroy() end; base:Destroy()
  if not ok then table.insert(out,key.." FAIL "..tostring(u)) else
    u.Name=NAMES[key]; u.UsePartColor=false; u.Anchored=true; u.CanCollide=false; u.CanQuery=false; u.CanTouch=false
    u.MaterialVariant="StudsSmall"
    u.PivotOffset=u.CFrame:ToObjectSpace(O)
    local oldU=props:FindFirstChild(NAMES[key]); if oldU then oldU:Destroy() end
    u.Parent=props
    table.insert(out,key.." ok size="..tostring(u.Size).." tris?")
  end
  task.wait()
end
return table.concat(out,"\n")
